import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch41Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm10_en_185","sm11_en_199","sm3-5_en_058","sm9_en_145","xy4_en_106","xy8_en_134");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static void play(ServerMatch m,UUID p){m.playTrainer(p,card(m,p,"trainer").instanceId(),null);}
    static void pick(ServerMatch m,UUID id){var q=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,q.resolutionId(),q.step(),id);}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static ServerMatch game(String id){return GeneratedRuleBatch8Test.fixture(List.of(),EnergyType.METAL,EnergyType.METAL,profile(id),GeneratedRuleBatch8Test.hit(100,false));}
    static ServerMatch aiGame(String id){var m=game(id);if(id.equals("xy4_en_106"))m.discardHandCardsByEffect(A,B,List.of(card(m,B,"basic").instanceId()));if(id.equals("sm11_en_199")||id.equals("sm3-5_en_058")){UUID p=id.equals("sm11_en_199")?B:A;m.placeDamageCountersByEffect(A,p,active(m,p),5);}return m;}
    public static void main(String[] args){jasmine();brigette();whistle();samson();transfer();System.out.println("NonPokemonBatch41Test passed: second-player first-turn search count, legacy EX versus GX/ex/V Bench search and space cap, opponent discard revival, shared dual-type Active comparison, and conserved own/opponent damage-counter movement");}
    static void jasmine(){for(boolean first:List.of(false,true)){
        var m=GeneratedRuleBatch8Test.fixture(List.of(),EnergyType.METAL,EnergyType.METAL,profile("sm9_en_145"),GeneratedRuleBatch8Test.hit(100,false),1,Set.of(),first);m.endTurn(A);int before=m.privateView(B).hand().size();play(m,B);var q=m.effectCardPrompt(B);check(q.maximum()==(first?5:1)&&q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).category()==CardCategory.POKEMON&&m.cardDefinition(c.definitionId()).pokemonTypes().contains(EnergyType.METAL)),"Jasmine count/type first="+first+" maximum="+q.maximum()+" candidates="+q.candidates());var chosen=q.candidates().stream().limit(q.maximum()).map(CardInstance::instanceId).toList();m.submitEffectCards(B,q.resolutionId(),q.step(),chosen);settle(m);check(m.privateView(B).hand().size()==before-1+chosen.size(),"Jasmine draw count or wrong owner");
    }}
    static void brigette(){for(PokemonFamily family:List.of(PokemonFamily.EX_LEGACY,PokemonFamily.EX,PokemonFamily.GX,PokemonFamily.V))for(boolean full:List.of(false,true)){
        var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile("xy8_en_134");c.ownFamilies=Set.of(family);var m=GeneratedRuleBatch28Test.fixture(c);if(full)while(m.benchPokemonView(A).size()<4)m.playBasicPokemonToBench(A,card(m,A,"attacker").instanceId());int benches=m.benchPokemonView(A).size();play(m,A);var choice=m.effectChoicePrompt(A);m.chooseEffectOption(A,choice.resolutionId(),choice.step(),family==PokemonFamily.EX_LEGACY?0:1);var q=m.effectCardPrompt(A);check(q.candidates().stream().allMatch(k->m.cardDefinition(k.definitionId()).basicPokemon()&&m.cardDefinition(k.definitionId()).pokemonFamilies().contains(PokemonFamily.EX_LEGACY)==(family==PokemonFamily.EX_LEGACY)),"Brigette confused legacy EX with ex/GX/V or accepted evolution");int count=Math.min(5-benches,Math.min(family==PokemonFamily.EX_LEGACY?1:3,q.candidates().size()));var cards=q.candidates().stream().limit(count).map(CardInstance::instanceId).toList();m.submitEffectCards(A,q.resolutionId(),q.step(),cards);settle(m);check(m.benchPokemonView(A).size()==benches+count,"Brigette wrong count or overfilled Bench");
    }}
    static void whistle(){var m=game("xy4_en_106");var basic=card(m,B,"basic");var evolved=card(m,B,"evolved");var own=card(m,A,"basic");m.discardHandCardsByEffect(A,B,List.of(basic.instanceId(),evolved.instanceId()));m.discardHandCardsByEffect(A,A,List.of(own.instanceId()));play(m,A);var q=m.effectCardPrompt(A);check(q.candidates().equals(List.of(basic)),"Target Whistle wrong source owner or stage");m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(basic.instanceId()));settle(m);check(m.benchPokemonView(B).size()==2&&m.benchPokemonView(A).size()==1&&!m.privateView(B).discard().contains(basic)&&m.privateView(B).discard().contains(evolved)&&m.privateView(A).discard().contains(own),"Target Whistle placed on wrong player's Bench");}
    static void samson(){for(Set<EnergyType> own:List.of(Set.of(EnergyType.FIRE),Set.of(EnergyType.WATER),Set.of(EnergyType.FIRE,EnergyType.WATER))){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile("sm10_en_185");c.ownTypes=own;c.defenderTypes=Set.of(EnergyType.WATER,EnergyType.GRASS);var m=GeneratedRuleBatch28Test.fixture(c);int before=m.privateView(A).hand().size();play(m,A);settle(m);check(m.privateView(A).hand().size()==before-1+(own.contains(EnergyType.WATER)?4:2),"Samson Oak compared exact type sets or wrong public Pokemon");}}
    static void transfer(){for(boolean opponent:List.of(false,true))for(int amount:opponent?List.of(1,2,3):List.of(3)){
        var m=game(opponent?"sm11_en_199":"sm3-5_en_058");UUID p=opponent?B:A,from=active(m,p),to=bench(m,p);m.placeDamageCountersByEffect(A,p,from,5);play(m,A);var q=m.effectPokemonPrompt(A);check(q.targets().stream().allMatch(t->t.owner().equals(p))&&q.targets().stream().anyMatch(t->t.pokemonId().equals(from)),"Counter source ownership");pick(m,from);check(m.effectPokemonPrompt(A).targets().stream().noneMatch(t->t.pokemonId().equals(from)),"Counter transfer allowed same source/destination");pick(m,to);if(opponent){var c=m.effectChoicePrompt(A);m.chooseEffectOption(A,c.resolutionId(),c.step(),amount-1);}settle(m);check(m.activePokemonView(p).damage()==50-amount*10&&m.benchPokemonView(p).getFirst().damage()==amount*10,"Counter move opponent="+opponent+" requested="+amount+" source="+m.activePokemonView(p).damage()+" recipient="+m.benchPokemonView(p).getFirst().damage());
    }var shortSource=game("sm3-5_en_058");shortSource.placeDamageCountersByEffect(A,A,active(shortSource,A),2);check(!shortSource.canPlayTrainer(A,card(shortSource,A,"trainer").instanceId(),null),"Damage Mover accepted fewer than three source counters");}
}
